-- Mensaje 112 · Tanda 2: apertura, bloqueos, historia breve y relación (Emilio, 30-oct-2026).
-- Orden: Cerebro → reglas → guiones. Todo protegido por su texto o versión de antes; el chequeo final aborta si algo no quedó.
DO $c$ DECLARE v int; BEGIN
  IF EXISTS (SELECT 1 FROM public.doctrina WHERE is_active AND strpos(body, $v$Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**. Encogerse en las palabras se ve así `CAMPO`: frases que se desinflan (*"bueno, pues… no, está bien"*), empezar a despedirse o a disculparse ante la indiferencia, contestar cada vez más corto y sin pregunta. Ir rápido y al grano, con seguridad, no es encogerse.$v$) > 0) THEN RAISE NOTICE 'El Cerebro ya tiene los cambios del 112.'; RETURN; END IF;
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$Lo que sí se evalúa es su equivalente verbal: **la energía que sale po$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee a$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$Convertir la observación en la pregunta final es como se sube de escalón.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$Convertir la observación en la pregunta final es como se sube de escal$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$> **La autoridad no se pide. Se asume.**$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$> **La autoridad no se pide. Se asume.**$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$> **El mecanismo:** cada frase de más gasta la atención que acabas de $v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE version = v AND strpos(body, $v$Sales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro vigente no tiene el texto esperado: %', $v$Sales de la línea a propósito, das **uno o dos intercambios personales$v$; END IF;
  INSERT INTO public.doctrina (version, section_key, order_index, title, body, is_active, created_by)
  SELECT v + 1, section_key, order_index, title, replace(replace(replace(replace(replace(replace(body, $v$Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**.$v$, $v$Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**. Encogerse en las palabras se ve así `CAMPO`: frases que se desinflan (*"bueno, pues… no, está bien"*), empezar a despedirse o a disculparse ante la indiferencia, contestar cada vez más corto y sin pregunta. Ir rápido y al grano, con seguridad, no es encogerse.$v$), $v$**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.$v$, $v$**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.

**En la práctica** `CAMPO`: lo que el vendedor ve se imagina. Lo que no se vale es contradecir lo que el cliente ya dijo: si dijo que hoy está tranquilo, no le digas que no para. Lo relativo no es contradicción —«mucha gente» para uno puede ser poca para otro—. Por eso el halago falso se juzga por exagerado o ensayado, no por inventado.$v$), $v$Convertir la observación en la pregunta final es como se sube de escalón.$v$, $v$Convertir la observación en la pregunta final es como se sube de escalón.

**Pregunta cerrada** `CAMPO`: la que falla no es la de sí o no, sino la que con su «no» le da la salida: *"¿tiene tiempo?"*, *"¿puedo pasar?"*, *"¿le interesa?"*. Una de sí o no sobre él o su negocio, que invita a platicar —*"¿así ha estado toda la semana?"*—, sí le devuelve la palabra.$v$), $v$> **La autoridad no se pide. Se asume.**$v$, $v$> **La autoridad no se pide. Se asume.**

**Ir rápido no es hacerse menos** `CAMPO`: *"de volada"*, *"al grano"* o *"nada más quería…"* van rápido sin pedir nada. Lo que hace chica tu presencia es pedir perdón por estar ahí o prometer que no le vas a quitar tiempo (*"no le quito mucho"*): le dices que sabes que estorbas.$v$), $v$> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.$v$, $v$> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.

**Cómo se mide** `CAMPO`: por piezas, no por frases. Cada pieza va una vez: quién eres, qué estás haciendo y por qué estás ahí. Una frase que explica el porqué es parte de esa pieza. Frase de más es la que no contesta ninguna de las tres: la trayectoria de la empresa, el catálogo, cifras, credenciales o explicar el producto.

**Monólogo** `CAMPO`: no se mide en palabras. Es el turno que el cliente no puede contestar bien porque le metiste varias ideas o varias preguntas a la vez, o un bloque largo que lo deja fuera.$v$), $v$Sales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando.$v$, $v$Sales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando. El interés genuino `CAMPO` se ve en lo que haces con lo que te contó: una pregunta de seguimiento o un comentario sobre eso. Un *"qué bien"* y cambiar de tema es interés de compromiso.$v$), true, created_by FROM public.doctrina WHERE version = v;
  UPDATE public.doctrina SET is_active = false WHERE is_active AND version = v;
END $c$;

UPDATE public.reglas SET resumen = $v$Agree, Ignore, Resume: ante un bloqueo al inicio, lo aceptas, no lo discutes y sigues con tu plática. LA PRUEBA: después del bloqueo, ¿el vendedor (1) reconoce lo que dijo el cliente («entiendo», «claro», «por supuesto» o algo que muestre que lo escuchó), (2) no trata de cambiar su no y (3) sigue con la plática —con otra pregunta o con lo que iba a decir— sin pedir permiso? Si hace las tres, cumple, aunque todavía no haya dicho a qué viene. Ir al grano («de volada», «nada más quería…») es seguir, no pedir permiso.$v$, cita_cerebro = $v$no lo discutas, y continúa$v$, updated_at = now() WHERE id = 'blocks.air' AND resumen = $v$Agree, Ignore, Resume: ante un bloqueo al inicio, lo aceptas, no lo discutes y sigues con tu plática. LA PRUEBA: después del bloqueo, ¿el vendedor (1) reconoce lo que dijo el cliente («entiendo», «claro», «por supuesto» o algo que muestre que lo escuchó), (2) no trata de cambiar su no y (3) sigue con la plática —con otra pregunta o con lo que iba a decir— sin pedir permiso? Si hace las tres, cumple, aunque todavía no haya dicho a qué viene. Ir al grano («de volada», «nada más quería…») es seguir, no pedir permiso.$v$ AND cita_cerebro = $v$reconoce con «entiendo» o «por supuesto», no lo discutas, y continúa$v$;
UPDATE public.reglas SET resumen = $v$Defenderse en tono de disculpa de algo que nadie reclamó. LA PRUEBA: ¿el vendedor se disculpa por adelantado o promete que él sí es diferente («perdón, pero yo sí soy diferente», «le prometo que con nosotros no pasa») sin dar nada concreto? Reconocer en serio lo que el cliente vivió y darle un motivo concreto no es esto.$v$, cita_cerebro = $v$deja de ser adelantarse y se vuelve defenderse de algo que nadie reclamó$v$, updated_at = now() WHERE id = 'blocks.ataque_en_disculpa' AND resumen = $v$Ataque preventivo en tono de disculpa: se vuelve defenderse de algo que nadie reclamó.$v$ AND cita_cerebro = $v$En tono de disculpa → deja de ser adelantarse y se vuelve defenderse de algo que nadie reclamó$v$;
UPDATE public.reglas SET resumen = $v$Discutir un bloqueo lo convierte en posición y le crea al cliente un no que no tenía. LA PRUEBA: ¿el vendedor trata de cambiar el no del cliente: convencerlo de que sí le interesa, de que sí tiene tiempo o de que será rápido? Si acepta el no y sigue con su tema, no es discutir, diga lo que diga.$v$, cita_cerebro = $v$Le acabas de crear un "no" real que no tenía$v$, updated_at = now() WHERE id = 'blocks.discute_bloqueo' AND resumen = $v$Discutir un bloqueo lo convierte en posición y le crea al cliente un no que no tenía. LA PRUEBA: ¿el vendedor trata de cambiar el no del cliente: convencerlo de que sí le interesa, de que sí tiene tiempo o de que será rápido? Si acepta el no y sigue con su tema, no es discutir, diga lo que diga.$v$ AND cita_cerebro = $v$Le acabas de crear un «no» real que no tenía$v$;
UPDATE public.reglas SET resumen = $v$Si haces AIR y el cliente repite el bloqueo de inmediato, son dos no seguidos: hoy no es el día. LA PRUEBA: después del segundo «no» seguido en la puerta, ¿el vendedor queda de regresar —mejor con una alternativa concreta, como jueves o viernes— o se despide con amabilidad, sin seguir con su tema? Cualquiera de las dos cumple; si sigue con su tema, no cumple.$v$, cita_cerebro = $v$si haces AIR y el cliente repite el bloqueo de inmediato, ya son dos no seguidos$v$, updated_at = now() WHERE id = 'blocks.dos_no_seguidos' AND resumen = $v$Si haces AIR y el cliente repite el bloqueo de inmediato, son dos no seguidos: hoy no es el día. Se queda de regresar en otro momento, con una alternativa concreta, o se despide con amabilidad. Tienen que ser consecutivos.$v$ AND cita_cerebro = $v$si haces AIR y el cliente repite el bloqueo de inmediato, ya son dos no seguidos$v$;
UPDATE public.reglas SET resumen = $v$Si el cliente saca una mala experiencia al llegar, no es un bloqueo para atravesar con AIR: es una preocupación real y se maneja como objeción. LA PRUEBA: ¿el vendedor (1) la acepta en serio, sin pelearla, minimizarla ni ignorarla; (2) da un motivo concreto de por qué viene ahora; y (3) regresa al diagnóstico con una pregunta? Si falta una pieza, está a medias. En la práctica todo es imaginario: el motivo se califica por concreto, no por real.$v$, cita_cerebro = $v$no es un bloqueo para atravesar con AIR: es una preocupación real y se maneja como objeción$v$, updated_at = now() WHERE id = 'blocks.mala_experiencia_al_llegar' AND resumen = $v$Si el cliente saca una mala experiencia al llegar, no es un bloqueo: se acepta en serio, se da el motivo real de la visita y se regresa al diagnóstico con una pregunta.$v$ AND cita_cerebro = $v$no es un bloqueo para atravesar con AIR: es una preocupación real y se maneja como objeción$v$;
UPDATE public.reglas SET resumen = $v$Turnos largos que no dejan entrar al cliente, en cualquier paso: de los discursos uno se defiende. LA PRUEBA: ¿hay un turno que el cliente no puede contestar bien porque le mete varias ideas o varias preguntas a la vez, o un bloque largo que lo deja fuera? No se mide en palabras, sino en si el cliente puede entrar.$v$, cita_cerebro = $v$de los discursos uno se defiende$v$, updated_at = now() WHERE id = 'monologo' AND resumen = $v$Turnos largos que no dejan entrar al cliente. En cualquier paso.$v$ AND cita_cerebro = $v$de los discursos uno se defiende$v$;
UPDATE public.reglas SET resumen = $v$Abrir sin identificarse deja al cliente con la pregunta. Que él pregunte quién eres es ganar la introducción: lo confirma, pero no es requisito — si el vendedor no se identificó, cumple. Identificarse es que el vendedor diga EN PRIMERA PERSONA quién es: "soy…", "me llamo…", "vengo de…", o el nombre de la empresa que representa. Usar el nombre DEL CLIENTE, o dirigirse a él con "don", "señor" o "sir", NO es identificarse: es personalización, y es bueno. LA PRUEBA: ¿el vendedor abrió sin decir en primera persona su nombre ni el de su empresa? Si sí, cumple.$v$, cita_cerebro = $v$esa pregunta es la puerta natural al Paso 2$v$, updated_at = now() WHERE id = 'opening.curiosidad_abierta' AND resumen = $v$Abrir sin identificarse deja al cliente con la pregunta. Que él pregunte quién eres es ganar la introducción: lo confirma, pero no es requisito — si el vendedor no se identificó, cumple. Identificarse es que el vendedor diga EN PRIMERA PERSONA quién es: "soy…", "me llamo…", "vengo de…", o el nombre de la empresa que representa. Usar el nombre DEL CLIENTE, o dirigirse a él con "don", "señor" o "sir", NO es identificarse: es personalización, y es bueno.$v$ AND cita_cerebro = $v$Si el cliente pregunta «¿y usted quién es?», ganaste la introducción — esa pregunta es la puerta natural al Paso 2$v$;
UPDATE public.reglas SET resumen = $v$El equivalente evaluable del SEE: la energía que sale por las palabras. LA PRUEBA: ante la indiferencia, la sequedad o la prisa del cliente, ¿el vendedor se encoge en lo que dice —frases que se desinflan («bueno, pues… no, está bien»), empieza a despedirse o a disculparse, contesta cada vez más corto y sin pregunta—? Entonces bajó la energía. Ir rápido y al grano, con seguridad, no es encogerse.$v$, cita_cerebro = $v$la energía que sale por las palabras$v$, updated_at = now() WHERE id = 'opening.energia_verbal' AND resumen = $v$El equivalente evaluable del SEE: la energía que sale por las palabras.$v$ AND cita_cerebro = $v$Lo que sí se evalúa es su equivalente verbal: la energía que sale por las palabras$v$;
UPDATE public.reglas SET resumen = $v$La escalera de la especificidad: la observación y la pregunta se miden por qué tan específicas son para ESE cliente en ESE momento — ¿se la harías a cualquiera? Escalón 1, de cortesía ("¿cómo está?"): acredita un tercio. Escalón 2, del entorno ("veo que no paran, ¿siempre está así de movido?"): acredita completo con cliente nuevo. Escalón 3, de él ("¿cómo sigue? ¿va mejorando?"): la meta con un recurrente. Las mismas palabras pueden estar en escalones distintos: lo que sube el escalón es qué tanto sabe de él. Un escalón bajo NO es una falla: se acredita menos y se muestra cómo subir. El escalón 3 exige historia REAL con el cliente: si la conversación no muestra ninguna, no está disponible y no se sugiere — jamás inventando un recuerdo. LA PRUEBA DEL ESCALÓN 2: nombra algo concreto que viste ahí —el movimiento, que está lleno, un cambio, algo nuevo—. Un adjetivo genérico ("qué bien se ve el local", "qué bonito") se lo dirías a cualquiera: es escalón 1. La especificidad NO mide si el comentario es ligero o si suena a inspección: eso lo mide el ice breaker. Contarle la mercancía ("cuatro cajas de filtros de una marca y dos de otra") es muy específico —escalón 2— aunque no rompa el hielo. En la práctica lo que el vendedor ve se imagina: no se califica si es real, solo que no contradiga lo que el cliente ya dijo.$v$, cita_cerebro = $v$La observación y la pregunta de la apertura se miden igual$v$, updated_at = now() WHERE id = 'opening.especificidad' AND resumen = $v$La escalera de la especificidad: la observación y la pregunta se miden por qué tan específicas son para ESE cliente en ESE momento — ¿se la harías a cualquiera? Escalón 1, de cortesía ("¿cómo está?"): acredita un tercio. Escalón 2, del entorno ("veo que no paran, ¿siempre está así de movido?"): acredita completo con cliente nuevo. Escalón 3, de él ("¿cómo sigue? ¿va mejorando?"): la meta con un recurrente. Las mismas palabras pueden estar en escalones distintos: lo que sube el escalón es qué tanto sabe de él. Un escalón bajo NO es una falla: se acredita menos y se muestra cómo subir. El escalón 3 exige historia REAL con el cliente: si la conversación no muestra ninguna, no está disponible y no se sugiere — jamás inventando un recuerdo. LA PRUEBA DEL ESCALÓN 2: nombra algo concreto que viste ahí —el movimiento, que está lleno, un cambio, algo nuevo—. Un adjetivo genérico ("qué bien se ve el local", "qué bonito") se lo dirías a cualquiera: es escalón 1. La especificidad NO mide si el comentario es ligero o si suena a inspección: eso lo mide el ice breaker. Contarle la mercancía ("cuatro cajas de filtros de una marca y dos de otra") es muy específico —escalón 2— aunque no rompa el hielo.$v$ AND cita_cerebro = $v$La observación y la pregunta de la apertura se miden igual$v$;
UPDATE public.reglas SET resumen = $v$La apertura tiene sus tres piezas: saludo, una observación y una pregunta que CIERRE el turno y le devuelva la palabra al cliente. Si están las tres y el turno termina con la pregunta —aunque sea de cortesía, como "¿cómo está?"—, este criterio se CUMPLE. Si la pregunta va en medio y el turno termina con un comentario, es parcial: falta que la pregunta cierre. Aquí solo se mide que las piezas estén; la calidad de cada una se mide en su propio criterio (la especificidad en la escalera, la ligereza en el ice breaker). Medirla también aquí sería castigar dos veces el mismo hecho. Si la pregunta es comercial, la pieza igual cuenta: lo comercial lo castiga pitch_prematuro, no la estructura. Castigarlo en los dos lados sería doble castigo. La pregunta que cierra se juzga por función: si la última frase invita a responder (aunque, en voz, no lleve signos) o el cliente la contestó, el turno termina en pregunta. LA PRUEBA: en su primer turno, ¿el vendedor saluda, hace una observación y termina con una pregunta? Si están las tres y la pregunta cierra el turno, cumple.$v$, cita_cerebro = $v$La pregunta va al final: es la que le devuelve la palabra al cliente$v$, updated_at = now() WHERE id = 'opening.estructura' AND resumen = $v$La apertura tiene sus tres piezas: saludo, una observación y una pregunta que CIERRE el turno y le devuelva la palabra al cliente. Si están las tres y el turno termina con la pregunta —aunque sea de cortesía, como "¿cómo está?"—, este criterio se CUMPLE. Si la pregunta va en medio y el turno termina con un comentario, es parcial: falta que la pregunta cierre. Aquí solo se mide que las piezas estén; la calidad de cada una se mide en su propio criterio (la especificidad en la escalera, la ligereza en el ice breaker). Medirla también aquí sería castigar dos veces el mismo hecho. Si la pregunta es comercial, la pieza igual cuenta: lo comercial lo castiga pitch_prematuro, no la estructura. Castigarlo en los dos lados sería doble castigo. La pregunta que cierra se juzga por función: si la última frase invita a responder (aunque, en voz, no lleve signos) o el cliente la contestó, el turno termina en pregunta.$v$ AND cita_cerebro = $v$La pregunta va al final: es la que le devuelve la palabra al cliente$v$;
UPDATE public.reglas SET resumen = $v$Halago exagerado o ensayado: el cliente lo lee al instante y se cierra más que antes, porque sabe que le están aplicando una técnica. LA PRUEBA: ¿el cumplido es desmedido para lo que hay («el mejor taller de toda la ciudad»), suena a fórmula, o contradice lo que el cliente ya dijo? Entonces es halago falso. En la práctica lo que el vendedor ve se imagina: no se califica si es real. Lo relativo («mucha gente», «muy movido») no es contradicción.$v$, cita_cerebro = $v$halago exagerado o inventado. El cliente lo lee al instante y se cierra$v$, updated_at = now() WHERE id = 'opening.halago_falso' AND resumen = $v$Halago exagerado o inventado. El cliente lo detecta y se cierra más que antes.$v$ AND cita_cerebro = $v$El halago exagerado o inventado. El cliente lo lee al instante y se cierra más que antes$v$;
UPDATE public.reglas SET resumen = $v$Cumplido genuino, chiste sencillo o comentario ligero sobre la persona, el lugar o algo en común. Entregarlo como pregunta es la forma que permite al cliente responder y relajarse. La ligereza se juzga en lo que dice el vendedor —humor suave, un guiño o calidez en las palabras—, nunca por la reacción del cliente: un buen chiste que no le hace gracia a un cliente rojo o de mal humor se hizo bien. Especificidad y ligereza son cosas distintas: esta regla mide la ligereza; la especificidad la mide opening.especificidad. LA PRUEBA: ¿el comentario tiene ligereza en lo que dice —humor suave, un guiño o calidez—, sobre la persona, el lugar o algo en común? Con una basta; un comentario solo descriptivo no la tiene.$v$, cita_cerebro = $v$Cumplido genuino, chiste sencillo o comentario ligero.$v$, updated_at = now() WHERE id = 'opening.ice_breaker' AND resumen = $v$Cumplido genuino, chiste sencillo o comentario ligero sobre la persona, el lugar o algo en común. Entregarlo como pregunta es la forma que permite al cliente responder y relajarse. La ligereza se juzga en lo que dice el vendedor —humor suave, un guiño o calidez en las palabras—, nunca por la reacción del cliente: un buen chiste que no le hace gracia a un cliente rojo o de mal humor se hizo bien. Especificidad y ligereza son cosas distintas: esta regla mide la ligereza; la especificidad la mide opening.especificidad.$v$ AND cita_cerebro = $v$Cumplido genuino, chiste sencillo o comentario ligero. Puede ser sobre la persona, el lugar, o algo en común$v$;
UPDATE public.reglas SET resumen = $v$Pedir autorización para hablar o para seguir: entrega el control y le ofrece al cliente una salida gratis. LA PRUEBA: ¿la frase le da al cliente la opción de decir que no a seguir la plática? Ejemplos que ilustran —no delimitan—: «¿tiene un minutito?», «¿me permite?», «¿le puedo preguntar algo?», «si no le molesta…». Si la frase no le da esa opción, no es pedir permiso, diga lo que diga. Pedir permiso es condicionar el seguir a que el cliente diga que sí: preguntárselo y esperar su respuesta, o ponerlo como condición («si no le molesta…»). Anunciar lo que vas a hacer y hacerlo en el mismo turno, sin condicionarlo —«quería preguntarle…» seguido de la pregunta—, no es pedir permiso: no le ofrece ninguna salida.$v$, cita_cerebro = $v$le entregas el control, y le ofreces una salida que no le cuesta nada tomar$v$, updated_at = now() WHERE id = 'opening.pide_permiso' AND resumen = $v$Pedir autorización para hablar o para seguir: entrega el control y le ofrece al cliente una salida gratis. LA PRUEBA: ¿la frase le da al cliente la opción de decir que no a seguir la plática? Ejemplos que ilustran —no delimitan—: «¿tiene un minutito?», «¿me permite?», «¿le puedo preguntar algo?», «si no le molesta…». Si la frase no le da esa opción, no es pedir permiso, diga lo que diga. Pedir permiso es condicionar el seguir a que el cliente diga que sí: preguntárselo y esperar su respuesta, o ponerlo como condición («si no le molesta…»). Anunciar lo que vas a hacer y hacerlo en el mismo turno, sin condicionarlo —«quería preguntarle…» seguido de la pregunta—, no es pedir permiso: no le ofrece ninguna salida.$v$ AND cita_cerebro = $v$Cuando preguntas «¿tiene un minutito?» haces dos cosas a la vez — le entregas el control, y le ofreces una salida que no le cuesta nada tomar$v$;
UPDATE public.reglas SET resumen = $v$Hacer trabajo comercial antes de tiempo. LA PRUEBA: ¿esta frase le ofrece algo o le pide información de su operación comercial? Si la respuesta es sí, es pitch prematuro, aunque no nombre ningún producto. Ejemplos que ilustran —no delimitan—: ofrecer producto o promoción; preguntar por su proveedor, sus precios, sus marcas, su inventario, sus volúmenes o cada cuánto le surten. NO es esto decir quién eres o por qué pasaste ("ando visitando talleres de la zona"): eso es presentarse, y su momento es el Paso 2. Tampoco una pregunta sobre él o sobre cómo le va.$v$, cita_cerebro = $v$no dices quién eres ni a qué vienes. Eso es el Paso 2.$v$, updated_at = now() WHERE id = 'opening.pitch_prematuro' AND resumen = $v$Hacer trabajo comercial antes de tiempo. LA PRUEBA: ¿esta frase le ofrece algo o le pide información de su operación comercial? Si la respuesta es sí, es pitch prematuro, aunque no nombre ningún producto. Ejemplos que ilustran —no delimitan—: ofrecer producto o promoción; preguntar por su proveedor, sus precios, sus marcas, su inventario, sus volúmenes o cada cuánto le surten. NO es esto decir quién eres o por qué pasaste ("ando visitando talleres de la zona"): eso es presentarse, y su momento es el Paso 2. Tampoco una pregunta sobre él o sobre cómo le va.$v$ AND cita_cerebro = $v$Aquí no dices quién eres ni a qué vienes. Eso es el Paso 2. Confundirlos es el error doctrinal más común$v$;
UPDATE public.reglas SET resumen = $v$Cerrar la apertura con una pregunta cuyo «no» le da al cliente la salida. LA PRUEBA: ¿la pregunta permite que el cliente termine la plática con un «no» —«¿tiene tiempo?», «¿puedo pasar?», «¿le interesa?», «¿está ocupado?»—? Una pregunta de sí o no sobre él o su negocio, que invita a platicar («¿así ha estado toda la semana?»), no es esta falla. (No hacer ninguna pregunta es otra falla: opening.sin_pregunta.)$v$, cita_cerebro = $v$la que con su «no» le da la salida$v$, updated_at = now() WHERE id = 'opening.pregunta_cerrada' AND resumen = $v$Cerrar la apertura con una pregunta de sí o no. Le entrega al cliente la respuesta más fácil, que es no. (No hacer ninguna pregunta es otra falla: opening.sin_pregunta.)$v$ AND cita_cerebro = $v$le ofreces una salida que no le cuesta nada tomar$v$;
UPDATE public.reglas SET resumen = $v$Create Personal Relations, durante toda la conversación: decide si tus argumentos pesan o se descuentan. LA PRUEBA: cuando el cliente deja ver algo personal —familia, trabajo, pasatiempos, motivaciones, deportes—, ¿el vendedor le entra con interés genuino (una pregunta de seguimiento o un comentario sobre eso) y luego regresa al negocio por su cuenta? Cuánto pide cada nodo lo dice el nodo.$v$, cita_cerebro = $v$Se aplica durante TODA la conversación$v$, updated_at = now() WHERE id = 'relationship.cpr' AND resumen = $v$Create Personal Relations. Transversal a toda la conversación. Decide si tus argumentos pesan o se descuentan.$v$ AND cita_cerebro = $v$Se aplica durante TODA la conversación, no en un paso$v$;
UPDATE public.reglas SET resumen = $v$Confianza que todavía no se ganó. Se construye en el registro del cliente. LA PRUEBA: ¿el vendedor usa apodos, tuteo, bromas personales o palmadas verbales («compadre», «mi rey») con un cliente que no le dio pie, en un registro más confianzudo que el del cliente?$v$, cita_cerebro = $v$Tú te adaptas primero$v$, updated_at = now() WHERE id = 'relationship.familiaridad_excesiva' AND resumen = $v$Confianza que todavía no se ganó: apodos, tuteo forzado. Se construye en el registro del cliente.$v$ AND cita_cerebro = $v$Tú te adaptas primero$v$;
UPDATE public.reglas SET resumen = $v$FORMS: Family, Occupation, Recreation, Motivation, Sports. Los cinco caminos a la persona. LA PRUEBA: ¿el vendedor toca al menos uno de esos temas con interés genuino y regresa al negocio por su cuenta en uno o dos intercambios?$v$, cita_cerebro = $v$Los cinco caminos a la persona. Más cumplidos genuinos y chistes sencillos$v$, updated_at = now() WHERE id = 'relationship.forms' AND resumen = $v$Family, Occupation, Recreation, Motivation, Sports. Los cinco caminos a la persona.$v$ AND cita_cerebro = $v$Los cinco caminos a la persona. Más cumplidos genuinos y chistes sencillos$v$;
UPDATE public.reglas SET resumen = $v$Interés fingido: cuesta más que no haber preguntado, porque el cliente sabe que le aplicaron una técnica. LA PRUEBA: ante algo personal que el cliente contó, ¿el vendedor contesta con un «qué bien» o «qué padre» y cambia de tema de inmediato, sin una pregunta de seguimiento ni un comentario sobre eso?$v$, cita_cerebro = $v$Un interés fingido se nota, y cuesta más que no haber preguntado$v$, updated_at = now() WHERE id = 'relationship.interes_fingido' AND resumen = $v$Interés fingido. Cuesta más que no haber preguntado, porque el cliente sabe que le aplicaron una técnica.$v$ AND cita_cerebro = $v$Un interés fingido se nota, y cuesta más que no haber preguntado$v$;
UPDATE public.reglas SET resumen = $v$Terminar la historia breve sin pregunta deja al cliente sin qué contestar y le devuelve el control. LA PRUEBA: ¿el turno de la historia breve termina en afirmación, sin una pregunta que le devuelva la palabra? La pregunta se juzga por función: si invita a responder o el cliente la contestó, es pregunta.$v$, cita_cerebro = $v$en la mayoría de los casos es más efectivo pasar directamente a las preguntas de calificación que dar una larga explicación$v$, updated_at = now() WHERE id = 'story.cierra_con_afirmacion' AND resumen = $v$Terminar la historia sin pregunta deja al cliente sin qué contestar y le devuelve el control.$v$ AND cita_cerebro = $v$en la mayoría de los casos es más efectivo pasar directamente a las preguntas de calificación que dar una larga explicación$v$;
UPDATE public.reglas SET resumen = $v$Alargarse: cada frase de más gasta la atención recién ganada y suena a discurso. LA PRUEBA: ¿la historia breve trae frases que no contestan quién eres, qué estás haciendo ni por qué estás ahí —la trayectoria de la empresa, el catálogo, cifras, credenciales o explicar el producto—? Una frase que explica el porqué es parte de esa pieza: no es de más.$v$, cita_cerebro = $v$frase de más gasta la atención que acabas de ganar$v$, updated_at = now() WHERE id = 'story.kill' AND resumen = $v$Alargarse. Cada frase de más gasta la atención recién ganada y suena a discurso.$v$ AND cita_cerebro = $v$Cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él$v$;
UPDATE public.reglas SET resumen = $v$Historia breve inflada con credenciales. LA PRUEBA: ¿el vendedor habla de los años, premios, tamaño o catálogo de su empresa en lugar de quién es él y por qué está ahí?$v$, cita_cerebro = $v$Lo que suena impresionante en tu cabeza suena a discurso en la de él$v$, updated_at = now() WHERE id = 'story.kill_curriculum' AND resumen = $v$Historia breve inflada con credenciales, años, catálogo.$v$ AND cita_cerebro = $v$Lo que suena impresionante en tu cabeza suena a discurso en la de él$v$;
UPDATE public.reglas SET resumen = $v$Keep It Short and Simple: quién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible. LA PRUEBA: ¿la historia breve trae sus piezas, cada una una vez, y nada que no conteste alguna de ellas? Se mide por piezas, no por frases: una frase que explica el porqué es parte de esa pieza. Si sobra algo —trayectoria, catálogo, cifras, credenciales, explicar el producto—, está a medias.$v$, cita_cerebro = $v$Quién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible$v$, updated_at = now() WHERE id = 'story.kiss' AND resumen = $v$Keep It Short and Simple. Lo más conciso posible.$v$ AND cita_cerebro = $v$Quién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible$v$;
UPDATE public.reglas SET resumen = $v$No salir nunca de la línea: sin relación, el Paso 3 recibe respuestas de cortesía. LA PRUEBA: cuando el cliente deja un dato personal, ¿el vendedor lo pasa de largo para seguir con lo suyo? O, en toda la plática, ¿nunca sale a lo personal aunque tuvo de dónde?$v$, cita_cerebro = $v$no hay relación, y no te van a contestar nada en el Paso 3$v$, updated_at = now() WHERE id = 'story.nunca_sale' AND resumen = $v$No salir nunca de la línea: sin relación, el Paso 3 recibe respuestas de cortesía.$v$ AND cita_cerebro = $v$Nunca salir → no hay relación, y no te van a contestar nada en el Paso 3$v$;
UPDATE public.reglas SET resumen = $v$Después de la historia, preguntas: la historia existe para ganarte el derecho de preguntarle a él. LA PRUEBA: ¿cada turno del vendedor termina con una pregunta que le devuelve la palabra al cliente? La pregunta se juzga por función: si invita a responder o el cliente la contestó, es pregunta.$v$, cita_cerebro = $v$Existe para ganarte el derecho de preguntarle a él$v$, updated_at = now() WHERE id = 'story.pregunta_despues' AND resumen = $v$Después de la historia, preguntas. La historia existe para ganarte el derecho de preguntarle a él.$v$ AND cita_cerebro = $v$Existe para ganarte el derecho de preguntarle a él$v$;
UPDATE public.reglas SET resumen = $v$Decir quién eres, qué estás haciendo y por qué necesitas su tiempo. LA PRUEBA: ¿el vendedor dice quién es —su nombre, y de qué empresa viene— y por qué está ahí, en términos humanos? Si falta una de las dos, está a medias.$v$, cita_cerebro = $v$Quién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible$v$, updated_at = now() WHERE id = 'story.quien_eres_por_que' AND resumen = $v$Decir quién eres, qué estás haciendo y por qué necesitas su tiempo.$v$ AND cita_cerebro = $v$Quién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible$v$;
UPDATE public.reglas SET resumen = $v$Salir a lo personal y no regresar: el cliente se acomoda a platicar y la venta se estanca. LA PRUEBA: después de salir a lo personal, ¿el vendedor deja pasar más de dos intercambios sin regresar al negocio por su cuenta? El cliente nunca te va a regresar a la línea.$v$, cita_cerebro = $v$el cliente se acomoda a platicar y la venta se estanca$v$, updated_at = now() WHERE id = 'story.sale_sin_regresar' AND resumen = $v$Salir a lo personal y no regresar. La venta se estanca en plática cómoda.$v$ AND cita_cerebro = $v$Salir y no regresar → el cliente se acomoda a platicar y la venta se estanca$v$;

UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 Mundo 1 reconstruido. R11 aplicada: la identificacion no se requiere ni se espera aqui. El espejo es la mecanica central: la respuesta del cliente es directamente proporcional a la especificidad de la observacion. v2.0.1 (oct-2026, Emilio): el Director puede cortar desde el primer turno; la apertura se demuestra en una frase y el vendedor no tiene que seguir improvisando lo que todavía no aprende. Decir quién eres o de qué empresa vienes no es pitch prematuro.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "opening.personalizacion", "opening.curiosidad_abierta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 1}, "phases": {"i_do": {"briefing": "Mira mi apertura y cuenta tres cosas: el saludo con energia, la observacion de algo real que veo, y la pregunta abierta al final.\n\nFijate sobre todo en la observacion — no digo algo que le diria a cualquiera, digo algo que solo aplica a EL. Esa es la parte que abre la puerta.", "first_message": "Buenos dias! Oiga, se ve que aqui no para el movimiento desde temprano.\n\nQue tal ha estado la semana?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. Estas en tu rutina normal, ni de buenas ni de malas, disponible pero no entusiasmado. Un desconocido acaba de llegar. TU REGLA PRINCIPAL: tu apertura depende ENTERAMENTE de la calidad de la primera frase del vendedor. Si su observacion es GENERICA (buenos dias, como esta, que tal todo) respondes con cortesia minima y corta — bien, gracias — y te quedas esperando, sin ofrecer nada. Si su observacion es ESPECIFICA de ti o de tu lugar (algo que noto de verdad y que no le diria a cualquiera), respondes con gusto, comentas algo de vuelta y la conversacion arranca sola. Si te hace una pregunta CERRADA de si o no (tiene un minuto, esta ocupado, puedo pasar), contestas lo mas facil: no, ahorita no. Y ya no ofreces nada mas. NUNCA preguntas que vende ni de que se trata a menos que el vendedor haya hecho las tres cosas bien. NUNCA hables tu de productos ni de negocio: este ejercicio es solo la apertura. Responde en 1 o 2 frases, natural, como habla un comerciante real.", "objective": "El vendedor ejecuta una apertura completa: saludo con energia, observacion especifica de ese cliente o ese lugar, y pregunta abierta que le devuelve la palabra. El scope se cubre cuando el cliente responde con gusto y comenta algo de vuelta por su propia voluntad. Identificarse con nombre y empresa es correcto pero NO se requiere en este nodo."}, "closing": {"message": "Eso es una apertura. Saludo con energia, observacion que solo aplica a el, y una pregunta que abre en lugar de cerrar. Con eso ya te ganaste los siguientes segundos. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como abres. Vamos al desglose y te digo cual era la siguiente pieza."}}, "version": "2.0.3", "i_do_type": "demo", "failure_criteria": [{"id": "pregunta_cerrada", "regla_id": "opening.pregunta_cerrada", "severity": "major", "description": "Cierra la apertura con una pregunta cuyo no le da la salida (tiene un minuto, puedo pasar, esta ocupado, le interesa). Una de si o no sobre el o su negocio que invita a platicar no es esto."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "En la apertura, ofrece producto o promoción, o pregunta por su operación comercial (proveedor, precios, marcas, volúmenes, cada cuánto le surten). Decir tu nombre o de qué empresa vienes NO es pitch prematuro, y menos si el cliente te lo preguntó: eso es la historia breve y en este nodo no se califica."}, {"id": "sin_pregunta", "regla_id": "opening.sin_pregunta", "severity": "critical", "description": "Saluda y observa pero no pregunta nada. La conversacion se muere ahi porque el cliente no tiene que contestar.", "severity_override": {"razon": "en el 1.2 es lo central del nodo: «Tu primera frase… terminas con una pregunta». Sin ninguna pregunta no aprendió el nodo y lo repite (Emilio, 17-oct-2026)", "default": "major"}}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.4, "regla_id": "opening.estructura", "description": "La apertura tiene sus tres piezas: saludo con energía, una observación y una pregunta que CIERRE el turno y le devuelva la palabra al cliente. Si están las tres y el turno termina con la pregunta —aunque sea de cortesía—, este criterio se cumple. Si la pregunta va en medio y el turno termina con un comentario, es parcial: falta que la pregunta cierre. La calidad de la pregunta y de la observación no se mide aquí: se mide en la escalera de la especificidad. Sin producto, sin motivo de venta. La identificación con nombre y empresa no se requiere aquí y su ausencia no se penaliza."}, {"id": "opening.personalizacion", "weight": 0.4, "regla_id": "opening.especificidad", "description": "La observacion y la pregunta se miden en la escalera de la especificidad: se la harias a cualquiera? Escalon 1, de cortesia (buen dia, como esta): acredita un tercio. Escalon 2, algo de ESA persona o ESE lugar en ESE momento: acredita completo. Una observacion inventada que el cliente no confirma no cumple."}, {"id": "opening.curiosidad_abierta", "weight": 0.2, "regla_id": "opening.curiosidad_abierta", "description": "Deja abierto quién es el vendedor: abre sin presentarse, es decir, sin decir en primera persona su propio nombre ni el de la empresa que representa. Si no se presentó, este criterio se cumple. Dirigirse al cliente por su nombre o con 'don', 'señor' o 'sir' NO es presentarse. Que el cliente termine preguntando quién es confirma que funcionó —y esa pregunta es la puerta natural al Paso 2—, pero que no lo pregunte no le quita nada. Presentarse de entrada no se penaliza: simplemente no acredita este criterio."}]}$g$::jsonb WHERE id = '1.2' AND practice_script->>'version' = '2.0.2';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 Nodo nuevo. El espejo tiene TRES estados y esa es la ensenanza: plano no abre, genuino abre, falso cierra mas que al inicio. Doctrina universal: el ice breaker puede ser sobre la persona, el entorno o algo en comun. No esta atado a ningun tipo de negocio. v2.0.1 (oct-2026, Emilio): el Director puede cortar desde el primer turno; la apertura se demuestra en una frase y el vendedor no tiene que seguir improvisando lo que todavía no aprende. Decir quién eres o de qué empresa vienes no es pitch prematuro.", "scope": {"skills_in_focus": ["opening.ice_breaker", "opening.personalizacion"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 1}, "phases": {"i_do": {"briefing": "Las dos frases dicen lo mismo, pero solo una rompe el hielo. Se ve mucho movimiento es plana: es verdad y no pasa nada.\n\nYa se le juntaron todos hoy, verdad? es ligera, tiene un guino, y el cliente contesta con humor.\n\nFijate en la diferencia, porque es toda la diferencia.", "first_message": "Buenas! Uy, veo que hoy se le juntaron todos al mismo tiempo, verdad?\n\nAsi o mas movido. Y siempre es asi los jueves o hoy le toco?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres una persona atendiendo su negocio. Empiezas con la guardia normal de quien ve llegar a un desconocido: cortes pero cerrado. TU REGLA PRINCIPAL: solo bajas la guardia si el vendedor dice algo LIGERO y GENUINO. Si su comentario es plano o meramente descriptivo (se ve movido, esta grande su local, hay mucha gente), contestas con un si seco o un ajam y te quedas igual de cerrado. Si su comentario tiene ligereza, humor suave o calidez real, y ademas es sobre algo verdadero de ti, de tu lugar o de algo que compartan, entonces sonries, contestas con humor de vuelta y ahi si baja la guardia: la conversacion se siente entre personas. Si el comentario suena FORZADO, ensayado, exagerado o falso (halagos desmedidos, chistes que no vienen al caso, familiaridad excesiva), te incomodas y te cierras MAS que al principio: contestas seco y cortante. NUNCA preguntes que vende. Responde en 1 o 2 frases, como habla la gente de verdad.", "objective": "El vendedor rompe el hielo con un comentario ligero y genuino sobre la persona, el lugar o algo en comun. El scope se cubre cuando el cliente baja la guardia de verdad: contesta con humor o calidez de vuelta y la conversacion pasa de tramite a conversacion entre personas."}, "closing": {"message": "Eso es romper el hielo. No fue un chiste ni un halago: fue un comentario ligero sobre algo verdadero. En un segundo dejaste de ser un vendedor tocando la puerta y te volviste una persona hablando con otra. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como entras. Vamos al desglose y te digo que le faltaba."}}, "version": "2.0.2", "i_do_type": "demo", "failure_criteria": [{"id": "halago_falso", "regla_id": "opening.halago_falso", "severity": "major", "description": "Cumplido exagerado, ensayado o que contradice lo que el cliente dijo. Cuesta mas de lo que gana: el cliente se cierra mas que al inicio."}, {"id": "familiaridad_excesiva", "regla_id": "relationship.familiaridad_excesiva", "severity": "minor", "description": "Confianza que todavia no se gano: apodos, bromas personales, tuteo forzado con alguien que no le dio pie."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Ofrece producto o promoción, o pregunta por su operación comercial (proveedor, precios, marcas, volúmenes, cada cuánto le surten). Decir tu nombre o de qué empresa vienes NO es pitch prematuro, y menos si el cliente te lo preguntó: eso es la historia breve y en este nodo no se califica."}], "success_criteria": [{"id": "opening.ice_breaker", "weight": 0.6, "regla_id": "opening.ice_breaker", "description": "El comentario tiene ligereza real: humor suave, un guino, calidez. No es solo descriptivo. Se distingue de una observacion plana en que invita a contestar con gusto, no solo a confirmar. Cualquier tema sirve: la persona, el lugar, el momento o algo en comun."}, {"id": "opening.personalizacion", "weight": 0.4, "regla_id": "opening.especificidad", "description": "El comentario es sobre algo especifico de ese cliente o ese momento. Un halago exagerado, ensayado o que contradice lo que el cliente dijo no cumple, y ademas cuesta: se siente falso. En la practica lo que se ve se imagina."}]}$g$::jsonb WHERE id = '1.5' AND practice_script->>'version' = '2.0.1';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 BOSS del Mundo 1. Sin pista garantizada y sin ayudas (R9): el gimnasio garantiza la oportunidad, el examen no. La senal de exito es que el cliente pregunte quien es el vendedor, que es la puerta natural al Mundo 2. v2.0.2 (oct-2026, Emilio): decir quién eres o de qué empresa vienes no es pitch prematuro. El Director puede cortar desde el primer turno: la introducción no obliga a un segundo turno.", "scope": {"skills_in_focus": ["opening.estructura_apertura", "opening.personalizacion", "opening.ice_breaker", "opening.arranque_sin_disculpa", "mindset.regla_10_por_ciento", "opening.curiosidad_abierta"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 8, "max_duration_seconds": 240, "min_turns_before_evaluation": 1}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Todo lo que practicaste por separado, junto y con un cliente que no ayuda.\n\nNo hay pistas ni facilidades: si la apertura no esta completa, el cliente no se abre.", "first_message": "Buenos dias! Ya lo vi en friega desde que venia llegando.\n\nSe nota que aqui no se descansa, eh? Oiga, y como ha estado la semana por aca?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y de pocas palabras. No eres grosero: eres alguien que ya vio pasar a muchos vendedores y no regala tiempo. TU COMPORTAMIENTO POR DEFECTO es cortes y cerrado: contestas en tres o cuatro palabras, sin ofrecer nada, sin preguntar nada. SOLO TE ABRES SI SE GANAN: si el vendedor se disculpa, pide permiso o se minimiza, lo despachas de inmediato con un ahorita ando ocupado. Si su observacion es generica o plana, contestas con monosilabos y sigues en lo tuyo. Si te hace una pregunta cerrada, contestas no y se acabo. Si el vendedor logra las tres cosas — entra con postura sin pedir permiso, dice algo ligero y verdadero que te haga sonreir o contestar de vuelta, y cierra con una pregunta abierta — entonces si: bajas la guardia, contestas con gusto, comentas algo de tu negocio por tu cuenta y le preguntas quien es. Esa pregunta es la senal de que gano la apertura. NUNCA preguntes quien es antes de que se lo gane. NUNCA hables de productos. Responde en 1 o 2 frases.", "objective": "El vendedor ejecuta la apertura completa frente a un cliente que no facilita nada: entra con postura y sin pedir permiso, rompe el hielo con algo ligero y verdadero, y abre con una pregunta que le devuelve la palabra. El scope se cubre cuando el cliente baja la guardia por su propia voluntad y pregunta quien es el vendedor, que es la puerta natural al siguiente paso."}, "closing": {"message": "Ahi esta la primera impresion completa. Entraste con postura, rompiste el hielo con algo verdadero y abriste la conversacion sin pedirle permiso a nadie. Ese cliente ya quiere saber quien eres, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.0.5", "i_do_type": "demo", "failure_criteria": [{"id": "pide_permiso", "regla_id": "opening.pide_permiso", "severity": "critical", "description": "Pide autorizacion en cualquier momento de la sesion. En el boss este error domina el resultado: la primera impresion murio ahi."}, {"id": "se_disculpa", "regla_id": "opening.se_disculpa", "severity": "critical", "description": "Se disculpa o minimiza su presencia en cualquier momento."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Ofrece producto o promoción, o pregunta por su operación comercial (proveedor, precios, marcas, volúmenes, cada cuánto le surten). Decir tu nombre o de qué empresa vienes NO es pitch prematuro, y menos si el cliente te lo preguntó: eso es la historia breve y en este nodo no se califica."}, {"id": "pregunta_cerrada", "regla_id": "opening.pregunta_cerrada", "severity": "major", "description": "Cierra la apertura con una pregunta cuyo no le da la salida (tiene un minuto, esta ocupado, le interesa)."}, {"id": "se_encoge", "regla_id": "opening.energia_verbal", "severity": "major", "description": "Ante la sequedad del cliente baja la energia o empieza a retirarse.", "espejo_de": "mindset.regla_10_por_ciento"}], "success_criteria": [{"id": "opening.estructura_apertura", "weight": 0.2, "regla_id": "opening.estructura", "description": "Las tres piezas presentes: saludo con energía, observación real y una pregunta que cierre el turno. Sin producto ni motivo de venta. Identificarse no se requiere aquí: eso es trabajo del Paso 2."}, {"id": "opening.personalizacion", "weight": 0.2, "regla_id": "opening.especificidad", "description": "La observacion es de ESE cliente y ESE momento, y no contradice lo que el cliente dice o hace. Nada generico."}, {"id": "opening.ice_breaker", "weight": 0.15, "regla_id": "opening.ice_breaker", "description": "Hay un cumplido genuino, un chiste sencillo o un comentario ligero —casual y amable, sin peso comercial— sobre la persona, el lugar o algo en común. Lo que no cumple es un comentario que suena a inspección: contarle la mercancía o describir en frío lo que ve."}, {"id": "opening.arranque_sin_disculpa", "weight": 0.2, "regla_id": "opening.gasman", "description": "Cero disculpas, cero peticiones de permiso, cero minimizarse durante TODA la sesion, incluso despues de una respuesta seca. Ir al grano no es minimizarse: «de rápido», «de volada» o «nada más quería…» le dicen al cliente que tú también vas rápido."}, {"id": "mindset.regla_10_por_ciento", "weight": 0.1, "regla_id": "opening.energia_verbal", "description": "Sostiene energia y postura frente a la sequedad del cliente. No se encoge, no baja el volumen, no empieza a despedirse."}, {"id": "opening.curiosidad_abierta", "weight": 0.15, "regla_id": "opening.curiosidad_abierta", "description": "Deja abierto quién es el vendedor: abre sin presentarse, es decir, sin decir en primera persona su propio nombre ni el de la empresa que representa. Si no se presentó, este criterio se cumple. Dirigirse al cliente por su nombre o con 'don', 'señor' o 'sir' NO es presentarse. Que el cliente termine preguntando quién es confirma que funcionó, pero que no lo pregunte no le quita nada. Presentarse de entrada no se penaliza: simplemente no acredita este criterio."}]}$g$::jsonb WHERE id = '1.6' AND practice_script->>'version' = '2.0.4';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 El espejo es progresivo: el cliente no corta de golpe, se va apagando conforme la historia se alarga. Ensena la consecuencia real de perder la atencion.", "scope": {"skills_in_focus": ["story.historia_breve", "story.brevedad", "story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 5, "max_duration_seconds": 150, "min_turns_before_evaluation": 2}, "phases": {"i_do": {"briefing": "Me van a preguntar quien soy.\n\nCuenta cuantas frases uso: tres. Quien soy, por que estoy aqui, y una pregunta que le devuelve la palabra.\n\nFijate en lo que NO digo: no cuento la historia de mi empresa, no enumero productos, no doy fechas ni cifras. Todo eso viene despues, y solo si el lo pide.", "first_message": "Soy Emilio, ando trabajando con los negocios de esta zona. Me tocaba pasar por aqui y quise conocer el suyo.\n\nCuenteme, cuanto tiempo lleva con el?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio. La conversacion arranco bien y acabas de preguntarle al vendedor quien es. TU REGLA PRINCIPAL: reaccionas al LARGO y a la RELEVANCIA de su respuesta. Si contesta breve (dos o tres frases) y te dice algo que a TI te importa, te relajas, contestas con gusto y sigues la conversacion. Si se extiende — historia de la empresa, anos en el mercado, lista de productos, certificaciones, mas de cuatro frases seguidas — empiezas a desconectarte: contestas con ajam, miras a otro lado, dices que andas ocupado. No lo cortas de golpe, te vas apagando. Si te habla puro de el y de su empresa sin conectar con tu negocio, contestas cortes pero sin interes. Si termina con una pregunta abierta, la contestas con gusto. Si termina sin pregunta, te quedas callado esperando, y el silencio se siente incomodo. NUNCA preguntes por productos ni precios en este ejercicio. Responde en 1 o 2 frases.", "objective": "El vendedor responde quien es en dos o tres frases, conectando su presencia con algo que le importe al cliente, y devuelve la palabra con una pregunta. El scope se cubre cuando el cliente se relaja y sigue la conversacion por su propia voluntad."}, "closing": {"message": "Eso es una historia breve. Quince segundos, dos piezas y un gancho. El cliente ya sabe con quien habla y sigue contigo, que es exactamente lo que este paso tiene que lograr. Vamos al detalle.", "message_incomplete": "Ahi lo dejamos, ya vi como te presentas. Vamos al desglose y te digo que le sobraba o que le faltaba."}}, "version": "2.0.1", "i_do_type": "demo", "failure_criteria": [{"id": "historia_larga", "regla_id": "story.kill", "severity": "major", "description": "Mete frases que no contestan quien es, que hace ni por que esta ahi: cuenta la trayectoria de la empresa, enumera productos, da cifras o certificaciones. El cliente se desconecta."}, {"id": "curriculum", "regla_id": "story.kill_curriculum", "severity": "major", "description": "Habla de si mismo y de su empresa sin conectar con el negocio del cliente. Correcto pero irrelevante."}, {"id": "sin_gancho", "regla_id": "story.cierra_con_afirmacion", "severity": "minor", "description": "Termina la historia sin devolver la palabra. Deja al cliente sin nada que contestar y la conversacion se queda en el aire.", "severity_override": {"razon": "incidental: fuera del foco del nodo", "default": "major"}}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Aprovecha la presentacion para meter producto, promocion o motivo de venta. La historia breve dice quien eres, no que vendes."}], "success_criteria": [{"id": "story.historia_breve", "weight": 0.4, "regla_id": "story.quien_eres_por_que", "description": "Dice quien es y por que esta ahi: nombre, de donde viene, y el motivo de la visita en terminos humanos. Las dos piezas presentes."}, {"id": "story.brevedad", "weight": 0.35, "regla_id": "story.kiss", "description": "Corta: quien es, que hace y por que esta ahi, cada pieza una vez. Sin historia de la empresa, anos en el mercado, lista de productos ni certificaciones. Se mide por piezas, no por frases: explicar el porque es parte de esa pieza."}, {"id": "story.relevancia_cliente", "weight": 0.25, "regla_id": "story.pregunta_despues", "description": "Conecta su presencia con algo que le importe al cliente, no consigo mismo. Y devuelve la palabra con una pregunta abierta en lugar de quedarse esperando."}]}$g$::jsonb WHERE id = '2.1' AND practice_script->>'version' = '2.0.0';
UPDATE public.nodes SET practice_script = $g${"notes": "v2.0.0 BOSS del Mundo 2. Sin pistas garantizadas (R9). Acumulativo: el Mundo 1 se examina implicitamente porque una apertura mal hecha no abre la conversacion. La senal de exito es que el cliente pregunte en que le puede servir, que es la puerta al Descubrimiento.", "scope": {"skills_in_focus": ["blocks.air", "story.historia_breve", "story.brevedad", "relationship.cpr", "flow.close_with_action", "story.relevancia_cliente"], "out_of_scope_behavior": "redirect"}, "limits": {"max_turns": 12, "max_duration_seconds": 300, "min_turns_before_evaluation": 4}, "phases": {"i_do": {"briefing": "Este es el examen del mundo. Bloqueo de entrada, historia breve, relacion personal y seguir avanzando: todo junto y con un cliente que no ayuda.\n\nSin pistas.", "first_message": "Entiendo perfecto, no se preocupe. Soy Emilio, ando trabajando con los negocios de esta zona y quise pasar a conocer el suyo.\n\nDigame una cosa, cuanto tiempo lleva usted aqui?"}, "you_do": {"prompt": "REGLA NUMERO CERO, POR ENCIMA DE TODO LO DEMAS: en esta conversacion NO EXISTE el tema de que vende este senor, que trae, a que viene, ni en que te puede servir. Jamas preguntas eso. Ni con esas palabras ni con ninguna otra. Prohibidas de forma absoluta las frases: que se le ofrece, que necesita, que anda buscando, a que viene, que trae, de que se trata, en que le puedo servir, y cualquier variante. Tu no sabes que es vendedor y no te interesa averiguarlo. Si el menciona por su cuenta un producto o una marca, contestas ah orale y sigues con lo tuyo sin preguntar nada. Si te quedas sin saber que decir, hablas de tu propio negocio o del dia, nunca de el.\n\nEres el encargado de un negocio, ocupado y con poca paciencia para vendedores. En tu PRIMERA respuesta sueltas un bloqueo de reflejo, con naturalidad y sin agresion: ahorita ando ocupado / no me interesa / no estoy comprando nada. TU COMPORTAMIENTO: eres cortes pero cerrado y contestas corto. NO ofreces informacion y NO llevas la conversacion. REGLAS DE REACCION: 1) Si el vendedor pelea el bloqueo, se disculpa o se va, lo despachas y la conversacion termina. 2) Si lo acepta y sigue, continuas con naturalidad. 3) Si su historia breve se alarga mas de tres o cuatro frases, te desconectas: contestas ajam y dices que andas ocupado. 4) Si el vendedor resuelve algo y se queda callado esperando, TU tomas el control y empiezas a despedirte con amabilidad. 5) En tu tercera o cuarta respuesta, si la conversacion sigue viva, sueltas de manera natural UN dato personal tuyo, al pasar, sin darle importancia: elige entre familia, como empezaste, que haces los domingos, por que pusiste el negocio, o tu equipo. Si el vendedor lo ignora, te enfrias y ya no ofreces nada mas de ti. Si le entra con interes real, te abres notablemente. Si se queda platicando de eso mas de dos intercambios sin volver al negocio, te acomodas a platicar de la vida y ya nunca regresas tu al tema. 6) SOLO si el vendedor logra todo — atravesar el bloqueo, decir quien es breve y relevante, conectar contigo como persona y regresar, y avanzar sin pedir permiso — entonces te abres de verdad: le cuentas algo de tu negocio por tu cuenta y le preguntas en que le puede servir. Esa pregunta es la senal de que gano. NUNCA la hagas antes de que se lo gane. Responde en 1 o 2 frases.", "objective": "El vendedor atraviesa el bloqueo inicial, se presenta en quince segundos de forma relevante, conecta con el dato personal y regresa, y sostiene el avance sin pedir permiso. El scope se cubre cuando el cliente se abre por su propia voluntad y pregunta en que le puede servir."}, "closing": {"message": "Ahi esta la puerta fria abierta. Atravesaste el bloqueo sin pelearlo, dijiste quien eras sin cansarlo, conectaste como persona y volviste, y nunca soltaste el control de la conversacion. Ese cliente ya quiere saber en que le puedes servir, y eso es exactamente lo que sigue. Vamos al detalle.", "message_incomplete": "Hasta aqui la sesion. Ya tengo lo que necesito para tu analisis. Vamos al desglose y te digo donde estuvo la diferencia."}}, "version": "2.1.5", "i_do_type": "demo", "failure_criteria": [{"id": "discute_el_bloqueo", "regla_id": "blocks.discute_bloqueo", "severity": "critical", "description": "Pelea el bloqueo inicial o intenta convencer al cliente de que si le interesa."}, {"id": "se_disculpa_o_se_va", "regla_id": "blocks.se_rinde_al_bloqueo", "severity": "critical", "description": "Ante el bloqueo, se disculpa, se despide o promete volver despues. Si el cliente REPITE el bloqueo justo despues del AIR (dos no seguidos), quedar de regresar en otro momento es lo correcto y no es esta falla."}, {"id": "se_queda_esperando", "regla_id": "close.devuelve_el_volante", "severity": "critical", "description": "Resuelve algo y se queda callado esperando permiso. El cliente toma el control y se despide.", "severity_override": {"razon": "boss: escalada", "default": "major"}}, {"id": "historia_larga", "regla_id": "story.kill", "severity": "major", "description": "La historia breve mete frases que no contestan quien es, que hace ni por que esta ahi, y el cliente se desconecta."}, {"id": "ignora_lo_personal", "regla_id": "story.nunca_sale", "severity": "major", "description": "Pasa de largo el dato personal que el cliente ofrecio.", "severity_override": {"razon": "boss: escalada", "default": "minor"}}, {"id": "se_queda_platicando", "regla_id": "story.sale_sin_regresar", "severity": "major", "description": "Le entra a lo personal y ya no vuelve al negocio."}, {"id": "pitch_prematuro", "regla_id": "opening.pitch_prematuro", "severity": "critical", "description": "Mete producto, promocion o motivo de venta. Identificarse con nombre y empresa es el trabajo de este paso, no una excepción: aquí SÍ se dice quién eres y por qué estás."}, {"id": "insiste_tras_dos", "regla_id": "blocks.insistir_tras_dos_no", "severity": "major", "description": "Después de dos no seguidos en la puerta sigue insistiendo: pide un minutito, vuelve a su tema o trata de convencerlo, en vez de quedar de regresar en otro momento. Ya no es seguridad, es terquedad. Solo cuenta lo que dice DESPUÉS del segundo no seguido."}], "success_criteria": [{"id": "blocks.air", "weight": 0.25, "regla_id": "blocks.air", "description": "Atraviesa el bloqueo inicial: lo acepta, no lo pelea, y sigue con la plática sin pedir permiso."}, {"id": "story.historia_breve", "weight": 0.15, "regla_id": "story.quien_eres_por_que", "description": "Dice quien es y por que esta ahi: nombre, procedencia y motivo humano de la visita."}, {"id": "story.brevedad", "weight": 0.1, "regla_id": "story.kiss", "description": "Corta: quien es, que hace y por que esta ahi, cada pieza una vez. Sin trayectoria de empresa, sin lista de productos, sin cifras."}, {"id": "relationship.cpr", "weight": 0.2, "regla_id": "relationship.cpr", "description": "Detecta el dato personal, le entra con interes genuino, y REGRESA al negocio por su cuenta en uno o dos intercambios."}, {"id": "flow.close_with_action", "weight": 0.15, "regla_id": "close_with_action", "description": "Despues de cada freno avanza por su cuenta, sin quedarse esperando ni pedir autorizacion. Sostiene el control de la conversacion toda la sesion."}, {"id": "story.relevancia_cliente", "weight": 0.15, "regla_id": "story.pregunta_despues", "description": "Sus turnos terminan devolviéndole la palabra al cliente con una pregunta: no deja afirmaciones sueltas en el aire."}]}$g$::jsonb WHERE id = '2.10' AND practice_script->>'version' = '2.1.4';

DO $chk$ DECLARE v int; n int; BEGIN
  SELECT max(version) INTO v FROM public.doctrina WHERE is_active;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active) <> 7 THEN RAISE EXCEPTION 'el Cerebro no tiene 7 secciones activas'; END IF;
  IF (SELECT count(DISTINCT version) FROM public.doctrina WHERE is_active) <> 1 THEN RAISE EXCEPTION 'hay más de una versión activa del Cerebro'; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$Lo que sí se evalúa es su equivalente verbal: **la energía que sale por las palabras**. Encogerse en las palabras se ve así `CAMPO`: frases que se desinflan (*"bueno, pues… no, está bien"*), empezar a despedirse o a disculparse ante la indiferencia, contestar cada vez más corto y sin pregunta. Ir rápido y al grano, con seguridad, no es encogerse.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$Lo que sí se evalúa es su equivalente verbal: **la energía que sale po$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee al instante y se cierra **más** que antes — porque ahora sabe que le están aplicando una técnica.

**En la práctica** `CAMPO`: lo que el vendedor ve se imagina. Lo que no se vale es contradecir lo que el cliente ya dijo: si dijo que hoy está tranquilo, no le digas que no para. Lo relativo no es contradicción —«mucha gente» para uno puede ser poca para otro—. Por eso el halago falso se juzga por exagerado o ensayado, no por inventado.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$**Qué lo rompe:** el halago exagerado o inventado. El cliente lo lee a$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$Convertir la observación en la pregunta final es como se sube de escalón.

**Pregunta cerrada** `CAMPO`: la que falla no es la de sí o no, sino la que con su «no» le da la salida: *"¿tiene tiempo?"*, *"¿puedo pasar?"*, *"¿le interesa?"*. Una de sí o no sobre él o su negocio, que invita a platicar —*"¿así ha estado toda la semana?"*—, sí le devuelve la palabra.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$Convertir la observación en la pregunta final es como se sube de escal$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$> **La autoridad no se pide. Se asume.**

**Ir rápido no es hacerse menos** `CAMPO`: *"de volada"*, *"al grano"* o *"nada más quería…"* van rápido sin pedir nada. Lo que hace chica tu presencia es pedir perdón por estar ahí o prometer que no le vas a quitar tiempo (*"no le quito mucho"*): le dices que sabes que estorbas.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$> **La autoridad no se pide. Se asume.**

**Ir rápido no es hacerse me$v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$> **El mecanismo:** cada frase de más gasta la atención que acabas de ganar. Lo que suena impresionante en tu cabeza suena a discurso en la de él — y de los discursos uno se defiende.

**Cómo se mide** `CAMPO`: por piezas, no por frases. Cada pieza va una vez: quién eres, qué estás haciendo y por qué estás ahí. Una frase que explica el porqué es parte de esa pieza. Frase de más es la que no contesta ninguna de las tres: la trayectoria de la empresa, el catálogo, cifras, credenciales o explicar el producto.

**Monólogo** `CAMPO`: no se mide en palabras. Es el turno que el cliente no puede contestar bien porque le metiste varias ideas o varias preguntas a la vez, o un bloque largo que lo deja fuera.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$> **El mecanismo:** cada frase de más gasta la atención que acabas de $v$; END IF;
  IF (SELECT count(*) FROM public.doctrina WHERE is_active AND strpos(body, $v$Sales de la línea a propósito, das **uno o dos intercambios personales**, y **regresas**. Puedes volver a salir más adelante, pero siempre avanzando. El interés genuino `CAMPO` se ve en lo que haces con lo que te contó: una pregunta de seguimiento o un comentario sobre eso. Un *"qué bien"* y cambiar de tema es interés de compromiso.$v$) > 0) <> 1 THEN RAISE EXCEPTION 'el Cerebro no recibió: %', $v$Sales de la línea a propósito, das **uno o dos intercambios personales$v$; END IF;
  SELECT count(*) INTO n FROM public.reglas r WHERE EXISTS (SELECT 1 FROM public.doctrina d WHERE d.version = v - 1 AND strpos(d.body, r.cita_cerebro) > 0) AND NOT EXISTS (SELECT 1 FROM public.doctrina d WHERE d.version = v AND strpos(d.body, r.cita_cerebro) > 0);
  IF n > 0 THEN RAISE EXCEPTION '% citas de reglas ya no están en el Cerebro', n; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.air') IS DISTINCT FROM $v$Agree, Ignore, Resume: ante un bloqueo al inicio, lo aceptas, no lo discutes y sigues con tu plática. LA PRUEBA: después del bloqueo, ¿el vendedor (1) reconoce lo que dijo el cliente («entiendo», «claro», «por supuesto» o algo que muestre que lo escuchó), (2) no trata de cambiar su no y (3) sigue con la plática —con otra pregunta o con lo que iba a decir— sin pedir permiso? Si hace las tres, cumple, aunque todavía no haya dicho a qué viene. Ir al grano («de volada», «nada más quería…») es seguir, no pedir permiso.$v$ THEN RAISE EXCEPTION 'la regla blocks.air no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'blocks.air' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de blocks.air no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.ataque_en_disculpa') IS DISTINCT FROM $v$Defenderse en tono de disculpa de algo que nadie reclamó. LA PRUEBA: ¿el vendedor se disculpa por adelantado o promete que él sí es diferente («perdón, pero yo sí soy diferente», «le prometo que con nosotros no pasa») sin dar nada concreto? Reconocer en serio lo que el cliente vivió y darle un motivo concreto no es esto.$v$ THEN RAISE EXCEPTION 'la regla blocks.ataque_en_disculpa no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'blocks.ataque_en_disculpa' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de blocks.ataque_en_disculpa no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.discute_bloqueo') IS DISTINCT FROM $v$Discutir un bloqueo lo convierte en posición y le crea al cliente un no que no tenía. LA PRUEBA: ¿el vendedor trata de cambiar el no del cliente: convencerlo de que sí le interesa, de que sí tiene tiempo o de que será rápido? Si acepta el no y sigue con su tema, no es discutir, diga lo que diga.$v$ THEN RAISE EXCEPTION 'la regla blocks.discute_bloqueo no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'blocks.discute_bloqueo' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de blocks.discute_bloqueo no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.dos_no_seguidos') IS DISTINCT FROM $v$Si haces AIR y el cliente repite el bloqueo de inmediato, son dos no seguidos: hoy no es el día. LA PRUEBA: después del segundo «no» seguido en la puerta, ¿el vendedor queda de regresar —mejor con una alternativa concreta, como jueves o viernes— o se despide con amabilidad, sin seguir con su tema? Cualquiera de las dos cumple; si sigue con su tema, no cumple.$v$ THEN RAISE EXCEPTION 'la regla blocks.dos_no_seguidos no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'blocks.dos_no_seguidos' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de blocks.dos_no_seguidos no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'blocks.mala_experiencia_al_llegar') IS DISTINCT FROM $v$Si el cliente saca una mala experiencia al llegar, no es un bloqueo para atravesar con AIR: es una preocupación real y se maneja como objeción. LA PRUEBA: ¿el vendedor (1) la acepta en serio, sin pelearla, minimizarla ni ignorarla; (2) da un motivo concreto de por qué viene ahora; y (3) regresa al diagnóstico con una pregunta? Si falta una pieza, está a medias. En la práctica todo es imaginario: el motivo se califica por concreto, no por real.$v$ THEN RAISE EXCEPTION 'la regla blocks.mala_experiencia_al_llegar no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'blocks.mala_experiencia_al_llegar' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de blocks.mala_experiencia_al_llegar no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'monologo') IS DISTINCT FROM $v$Turnos largos que no dejan entrar al cliente, en cualquier paso: de los discursos uno se defiende. LA PRUEBA: ¿hay un turno que el cliente no puede contestar bien porque le mete varias ideas o varias preguntas a la vez, o un bloque largo que lo deja fuera? No se mide en palabras, sino en si el cliente puede entrar.$v$ THEN RAISE EXCEPTION 'la regla monologo no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'monologo' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de monologo no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.curiosidad_abierta') IS DISTINCT FROM $v$Abrir sin identificarse deja al cliente con la pregunta. Que él pregunte quién eres es ganar la introducción: lo confirma, pero no es requisito — si el vendedor no se identificó, cumple. Identificarse es que el vendedor diga EN PRIMERA PERSONA quién es: "soy…", "me llamo…", "vengo de…", o el nombre de la empresa que representa. Usar el nombre DEL CLIENTE, o dirigirse a él con "don", "señor" o "sir", NO es identificarse: es personalización, y es bueno. LA PRUEBA: ¿el vendedor abrió sin decir en primera persona su nombre ni el de su empresa? Si sí, cumple.$v$ THEN RAISE EXCEPTION 'la regla opening.curiosidad_abierta no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.curiosidad_abierta' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.curiosidad_abierta no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.energia_verbal') IS DISTINCT FROM $v$El equivalente evaluable del SEE: la energía que sale por las palabras. LA PRUEBA: ante la indiferencia, la sequedad o la prisa del cliente, ¿el vendedor se encoge en lo que dice —frases que se desinflan («bueno, pues… no, está bien»), empieza a despedirse o a disculparse, contesta cada vez más corto y sin pregunta—? Entonces bajó la energía. Ir rápido y al grano, con seguridad, no es encogerse.$v$ THEN RAISE EXCEPTION 'la regla opening.energia_verbal no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.energia_verbal' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.energia_verbal no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.especificidad') IS DISTINCT FROM $v$La escalera de la especificidad: la observación y la pregunta se miden por qué tan específicas son para ESE cliente en ESE momento — ¿se la harías a cualquiera? Escalón 1, de cortesía ("¿cómo está?"): acredita un tercio. Escalón 2, del entorno ("veo que no paran, ¿siempre está así de movido?"): acredita completo con cliente nuevo. Escalón 3, de él ("¿cómo sigue? ¿va mejorando?"): la meta con un recurrente. Las mismas palabras pueden estar en escalones distintos: lo que sube el escalón es qué tanto sabe de él. Un escalón bajo NO es una falla: se acredita menos y se muestra cómo subir. El escalón 3 exige historia REAL con el cliente: si la conversación no muestra ninguna, no está disponible y no se sugiere — jamás inventando un recuerdo. LA PRUEBA DEL ESCALÓN 2: nombra algo concreto que viste ahí —el movimiento, que está lleno, un cambio, algo nuevo—. Un adjetivo genérico ("qué bien se ve el local", "qué bonito") se lo dirías a cualquiera: es escalón 1. La especificidad NO mide si el comentario es ligero o si suena a inspección: eso lo mide el ice breaker. Contarle la mercancía ("cuatro cajas de filtros de una marca y dos de otra") es muy específico —escalón 2— aunque no rompa el hielo. En la práctica lo que el vendedor ve se imagina: no se califica si es real, solo que no contradiga lo que el cliente ya dijo.$v$ THEN RAISE EXCEPTION 'la regla opening.especificidad no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.especificidad' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.especificidad no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.estructura') IS DISTINCT FROM $v$La apertura tiene sus tres piezas: saludo, una observación y una pregunta que CIERRE el turno y le devuelva la palabra al cliente. Si están las tres y el turno termina con la pregunta —aunque sea de cortesía, como "¿cómo está?"—, este criterio se CUMPLE. Si la pregunta va en medio y el turno termina con un comentario, es parcial: falta que la pregunta cierre. Aquí solo se mide que las piezas estén; la calidad de cada una se mide en su propio criterio (la especificidad en la escalera, la ligereza en el ice breaker). Medirla también aquí sería castigar dos veces el mismo hecho. Si la pregunta es comercial, la pieza igual cuenta: lo comercial lo castiga pitch_prematuro, no la estructura. Castigarlo en los dos lados sería doble castigo. La pregunta que cierra se juzga por función: si la última frase invita a responder (aunque, en voz, no lleve signos) o el cliente la contestó, el turno termina en pregunta. LA PRUEBA: en su primer turno, ¿el vendedor saluda, hace una observación y termina con una pregunta? Si están las tres y la pregunta cierra el turno, cumple.$v$ THEN RAISE EXCEPTION 'la regla opening.estructura no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.estructura' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.estructura no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.halago_falso') IS DISTINCT FROM $v$Halago exagerado o ensayado: el cliente lo lee al instante y se cierra más que antes, porque sabe que le están aplicando una técnica. LA PRUEBA: ¿el cumplido es desmedido para lo que hay («el mejor taller de toda la ciudad»), suena a fórmula, o contradice lo que el cliente ya dijo? Entonces es halago falso. En la práctica lo que el vendedor ve se imagina: no se califica si es real. Lo relativo («mucha gente», «muy movido») no es contradicción.$v$ THEN RAISE EXCEPTION 'la regla opening.halago_falso no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.halago_falso' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.halago_falso no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.ice_breaker') IS DISTINCT FROM $v$Cumplido genuino, chiste sencillo o comentario ligero sobre la persona, el lugar o algo en común. Entregarlo como pregunta es la forma que permite al cliente responder y relajarse. La ligereza se juzga en lo que dice el vendedor —humor suave, un guiño o calidez en las palabras—, nunca por la reacción del cliente: un buen chiste que no le hace gracia a un cliente rojo o de mal humor se hizo bien. Especificidad y ligereza son cosas distintas: esta regla mide la ligereza; la especificidad la mide opening.especificidad. LA PRUEBA: ¿el comentario tiene ligereza en lo que dice —humor suave, un guiño o calidez—, sobre la persona, el lugar o algo en común? Con una basta; un comentario solo descriptivo no la tiene.$v$ THEN RAISE EXCEPTION 'la regla opening.ice_breaker no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.ice_breaker' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.ice_breaker no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.pide_permiso') IS DISTINCT FROM $v$Pedir autorización para hablar o para seguir: entrega el control y le ofrece al cliente una salida gratis. LA PRUEBA: ¿la frase le da al cliente la opción de decir que no a seguir la plática? Ejemplos que ilustran —no delimitan—: «¿tiene un minutito?», «¿me permite?», «¿le puedo preguntar algo?», «si no le molesta…». Si la frase no le da esa opción, no es pedir permiso, diga lo que diga. Pedir permiso es condicionar el seguir a que el cliente diga que sí: preguntárselo y esperar su respuesta, o ponerlo como condición («si no le molesta…»). Anunciar lo que vas a hacer y hacerlo en el mismo turno, sin condicionarlo —«quería preguntarle…» seguido de la pregunta—, no es pedir permiso: no le ofrece ninguna salida.$v$ THEN RAISE EXCEPTION 'la regla opening.pide_permiso no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.pide_permiso' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.pide_permiso no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.pitch_prematuro') IS DISTINCT FROM $v$Hacer trabajo comercial antes de tiempo. LA PRUEBA: ¿esta frase le ofrece algo o le pide información de su operación comercial? Si la respuesta es sí, es pitch prematuro, aunque no nombre ningún producto. Ejemplos que ilustran —no delimitan—: ofrecer producto o promoción; preguntar por su proveedor, sus precios, sus marcas, su inventario, sus volúmenes o cada cuánto le surten. NO es esto decir quién eres o por qué pasaste ("ando visitando talleres de la zona"): eso es presentarse, y su momento es el Paso 2. Tampoco una pregunta sobre él o sobre cómo le va.$v$ THEN RAISE EXCEPTION 'la regla opening.pitch_prematuro no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.pitch_prematuro' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.pitch_prematuro no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'opening.pregunta_cerrada') IS DISTINCT FROM $v$Cerrar la apertura con una pregunta cuyo «no» le da al cliente la salida. LA PRUEBA: ¿la pregunta permite que el cliente termine la plática con un «no» —«¿tiene tiempo?», «¿puedo pasar?», «¿le interesa?», «¿está ocupado?»—? Una pregunta de sí o no sobre él o su negocio, que invita a platicar («¿así ha estado toda la semana?»), no es esta falla. (No hacer ninguna pregunta es otra falla: opening.sin_pregunta.)$v$ THEN RAISE EXCEPTION 'la regla opening.pregunta_cerrada no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'opening.pregunta_cerrada' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de opening.pregunta_cerrada no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'relationship.cpr') IS DISTINCT FROM $v$Create Personal Relations, durante toda la conversación: decide si tus argumentos pesan o se descuentan. LA PRUEBA: cuando el cliente deja ver algo personal —familia, trabajo, pasatiempos, motivaciones, deportes—, ¿el vendedor le entra con interés genuino (una pregunta de seguimiento o un comentario sobre eso) y luego regresa al negocio por su cuenta? Cuánto pide cada nodo lo dice el nodo.$v$ THEN RAISE EXCEPTION 'la regla relationship.cpr no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'relationship.cpr' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de relationship.cpr no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'relationship.familiaridad_excesiva') IS DISTINCT FROM $v$Confianza que todavía no se ganó. Se construye en el registro del cliente. LA PRUEBA: ¿el vendedor usa apodos, tuteo, bromas personales o palmadas verbales («compadre», «mi rey») con un cliente que no le dio pie, en un registro más confianzudo que el del cliente?$v$ THEN RAISE EXCEPTION 'la regla relationship.familiaridad_excesiva no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'relationship.familiaridad_excesiva' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de relationship.familiaridad_excesiva no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'relationship.forms') IS DISTINCT FROM $v$FORMS: Family, Occupation, Recreation, Motivation, Sports. Los cinco caminos a la persona. LA PRUEBA: ¿el vendedor toca al menos uno de esos temas con interés genuino y regresa al negocio por su cuenta en uno o dos intercambios?$v$ THEN RAISE EXCEPTION 'la regla relationship.forms no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'relationship.forms' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de relationship.forms no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'relationship.interes_fingido') IS DISTINCT FROM $v$Interés fingido: cuesta más que no haber preguntado, porque el cliente sabe que le aplicaron una técnica. LA PRUEBA: ante algo personal que el cliente contó, ¿el vendedor contesta con un «qué bien» o «qué padre» y cambia de tema de inmediato, sin una pregunta de seguimiento ni un comentario sobre eso?$v$ THEN RAISE EXCEPTION 'la regla relationship.interes_fingido no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'relationship.interes_fingido' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de relationship.interes_fingido no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.cierra_con_afirmacion') IS DISTINCT FROM $v$Terminar la historia breve sin pregunta deja al cliente sin qué contestar y le devuelve el control. LA PRUEBA: ¿el turno de la historia breve termina en afirmación, sin una pregunta que le devuelva la palabra? La pregunta se juzga por función: si invita a responder o el cliente la contestó, es pregunta.$v$ THEN RAISE EXCEPTION 'la regla story.cierra_con_afirmacion no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'story.cierra_con_afirmacion' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de story.cierra_con_afirmacion no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.kill') IS DISTINCT FROM $v$Alargarse: cada frase de más gasta la atención recién ganada y suena a discurso. LA PRUEBA: ¿la historia breve trae frases que no contestan quién eres, qué estás haciendo ni por qué estás ahí —la trayectoria de la empresa, el catálogo, cifras, credenciales o explicar el producto—? Una frase que explica el porqué es parte de esa pieza: no es de más.$v$ THEN RAISE EXCEPTION 'la regla story.kill no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'story.kill' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de story.kill no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.kill_curriculum') IS DISTINCT FROM $v$Historia breve inflada con credenciales. LA PRUEBA: ¿el vendedor habla de los años, premios, tamaño o catálogo de su empresa en lugar de quién es él y por qué está ahí?$v$ THEN RAISE EXCEPTION 'la regla story.kill_curriculum no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'story.kill_curriculum' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de story.kill_curriculum no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.kiss') IS DISTINCT FROM $v$Keep It Short and Simple: quién eres, qué estás haciendo, por qué necesitas su tiempo. Lo más conciso posible. LA PRUEBA: ¿la historia breve trae sus piezas, cada una una vez, y nada que no conteste alguna de ellas? Se mide por piezas, no por frases: una frase que explica el porqué es parte de esa pieza. Si sobra algo —trayectoria, catálogo, cifras, credenciales, explicar el producto—, está a medias.$v$ THEN RAISE EXCEPTION 'la regla story.kiss no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'story.kiss' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de story.kiss no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.nunca_sale') IS DISTINCT FROM $v$No salir nunca de la línea: sin relación, el Paso 3 recibe respuestas de cortesía. LA PRUEBA: cuando el cliente deja un dato personal, ¿el vendedor lo pasa de largo para seguir con lo suyo? O, en toda la plática, ¿nunca sale a lo personal aunque tuvo de dónde?$v$ THEN RAISE EXCEPTION 'la regla story.nunca_sale no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'story.nunca_sale' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de story.nunca_sale no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.pregunta_despues') IS DISTINCT FROM $v$Después de la historia, preguntas: la historia existe para ganarte el derecho de preguntarle a él. LA PRUEBA: ¿cada turno del vendedor termina con una pregunta que le devuelve la palabra al cliente? La pregunta se juzga por función: si invita a responder o el cliente la contestó, es pregunta.$v$ THEN RAISE EXCEPTION 'la regla story.pregunta_despues no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'story.pregunta_despues' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de story.pregunta_despues no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.quien_eres_por_que') IS DISTINCT FROM $v$Decir quién eres, qué estás haciendo y por qué necesitas su tiempo. LA PRUEBA: ¿el vendedor dice quién es —su nombre, y de qué empresa viene— y por qué está ahí, en términos humanos? Si falta una de las dos, está a medias.$v$ THEN RAISE EXCEPTION 'la regla story.quien_eres_por_que no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'story.quien_eres_por_que' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de story.quien_eres_por_que no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'story.sale_sin_regresar') IS DISTINCT FROM $v$Salir a lo personal y no regresar: el cliente se acomoda a platicar y la venta se estanca. LA PRUEBA: después de salir a lo personal, ¿el vendedor deja pasar más de dos intercambios sin regresar al negocio por su cuenta? El cliente nunca te va a regresar a la línea.$v$ THEN RAISE EXCEPTION 'la regla story.sale_sin_regresar no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'story.sale_sin_regresar' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de story.sale_sin_regresar no está en el Cerebro'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '1.2') IS DISTINCT FROM 'cb158d29d2a0d5530e5e51009b263802' THEN RAISE EXCEPTION 'el guion del 1.2 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '1.5') IS DISTINCT FROM '466d266eec75ca15f255db60bb6f2e7d' THEN RAISE EXCEPTION 'el guion del 1.5 no quedó'; END IF;
  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '1.6') IS DISTINCT FROM 'cf67ca71022b8d544a1f8dd8168764fc' THEN RAISE EXCEPTION 'el guion del 1.6 no quedó'; END IF;
