  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '2.10') IS DISTINCT FROM '8bdd710f8070e2ad53cf32617d261912' THEN RAISE EXCEPTION 'el guion del 2.10 no quedó'; END IF;
